package com.gomgomapps.math.core;
import java.util.*;import java.util.regex.*;import org.junit.Test;import static org.junit.Assert.*;
public class PrismSurfaceRelationsTest {
 @Test public void publicRightTriangleDimensionsIndependentlyDetermineSurface(){Generator g=new Generator(new Random(1850));for(int i=0;i<600;i++){Question q=g.next("triangularPrismSurface",List.of(),i%2==0);Matcher m=Pattern.compile("\\d+(?:\\.\\d+)?").matcher(q.prompt);List<Rational> v=new ArrayList<>();while(m.find())v.add(Expression.number(m.group()));assertEquals(4,v.size());Rational length=v.get(0),a=v.get(1),b=v.get(2),c=v.get(3);assertEquals(a.mul(a).add(b.mul(b)),c.mul(c));Rational area=a.mul(b).div(Rational.of(2)),perimeter=a.add(b).add(c),sides=perimeter.mul(length),answer=area.mul(Rational.of(2)).add(sides);assertTrue(new Checker().check(q,List.of(),List.of(answer.toString())).correct());verify(q,List.of(a,b,c,length,area,perimeter,sides,answer));}}
 @Test public void savedFractionalDimensionsRemainExact(){verify(new Question("triangularPrismSurface","곧은 삼각기둥 · 길이 2/3cm\n밑면: 직각삼각형\n직각의 두 변 1cm, 4/3cm · 빗변 5/3cm\n겉넓이는 몇 cm²인가요?","","4"),List.of(Rational.ONE,Rational.of(4,3),Rational.of(5,3),Rational.of(2,3),Rational.of(2,3),Rational.of(4),Rational.of(8,3),Rational.of(4)));}
 @Test public void oldBaseAreaDraftCannotBecomeFirstSide(){Question q=new Question("triangularPrismSurface","곧은 삼각기둥 · 길이 8cm\n밑면: 직각삼각형\n직각의 두 변 3cm, 4cm · 빗변 5cm\n겉넓이는 몇 cm²인가요?","","108");HelpPlan p=HelpPlan.forQuestion(q);HelpPlan.Draft d=new HelpPlan.Draft();d.questionId=q.id;d.stage=1;d.entries=new ArrayList<>(List.of("6",""));p.restore(d,q.id);assertEquals(0,d.stage);assertEquals("",d.entries.get(0));d.entries.set(0,"3");d.stage=1;HelpPlan.Draft restored=HelpPlan.forQuestion(q).restore(d.copy(),q.id);assertEquals(1,restored.stage);assertEquals("3",restored.entries.get(0));}
 private void verify(Question q,List<Rational> expected){String signature=q.signature();Arrays.fill(q.answers,"999999");q.choiceInputs=new Rational[]{Rational.of(999999)};HelpPlan p=HelpPlan.forQuestion(q);assertEquals(signature,q.signature());assertEquals(8,p.size());assertFalse(p.canTransfer());for(int k=0;k<8;k++){assertTrue(p.step(k).accepts(expected.get(k).toString()));assertFalse(p.step(k).accepts(expected.get(k).add(Rational.ONE).toString()));assertFalse(p.step(k).before.replace("2","").matches("(?s).*\\d.*"));}}
}
